create table FM_SERVICE_DEFINE (MESSAGE_CODE VARCHAR(20) not null  ,COMPANY VARCHAR(20) null  ,ACROSS_BRAN_CHECK_FLAG VARCHAR(1) not null  ,BUSI_CATEGORY VARCHAR(20) not null  ,SERVICE_STATUS VARCHAR(20) not null  ,BLACKLIST_CHECK_FLAG VARCHAR(1) not null  ,SERVICE_CODE VARCHAR(30) not null  ,MULTI_CORP_CHECK_FLAG VARCHAR(1) not null  ,ALLOW_REVERSE_FLAG VARCHAR(1) not null  ,MESSAGE_TYPE VARCHAR(20) not null  ,WHITE_LIST_CHECK_FLAG VARCHAR(1) not null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,BUSI_SUB_CLASS VARCHAR(10) null  ,CLIENT_CHECK_FLAG VARCHAR(1) not null  ,URL VARCHAR(200) not null  , primary key(MESSAGE_CODE,SERVICE_CODE,MESSAGE_TYPE));